LABELS={k.casefold():v for k,v in LABELS.items()}
def label(raw):
 if re.search('[А-Яа-яЁё]',raw):return raw
 if raw.casefold() in LABELS:return LABELS[raw.casefold()]
 replacements={'Charging Case':'Зарядный кейс','Earpiece':'Наушник (один или пара не уточнено)','Earbud':'Наушник (один или пара не уточнено)','Ear Cup':'Амбушюра','External':'Внешняя','Internal':'Внутренняя','Height':'Высота','Width':'Ширина','Depth':'Глубина','Weight':'Вес','Dimensions':'Габариты','Headphone cable length':'Длина кабеля наушников','Battery':'Аккумулятор','Capacity':'Ёмкость','Charging':'Зарядка','Bluetooth':'Bluetooth'}
 for a,b in replacements.items():raw=raw.replace(a,b)
 return raw
def section(raw):
 v=raw.casefold()
 v={'ukuran':'dimensions','baterai':'battery','fitur':'features','spesifikasi audio':'audio specifications','spesifikasi kontrol dan koneksi':'control and connection specifications','spesifikasi general':'general specifications'}.get(v,v)
 if any(x in v for x in ['dimension','abmess','weight','габарит','вес']):return 'Габариты и вес'
 if v in {'battery','akku'}:return 'Аккумулятор и время работы'
 if 'audio' in v:return 'Аудио'
 if 'connection' in v or 'verbindung' in v:return 'Подключение'
 if v in {'features','ausstattung'}:return 'Особенности модели'
 return 'Основные характеристики' if v in {'specifications','general specifications','allgemeine spezifikationen'} else raw

def project(rows):
 result=[]
 for original in rows:
  row={**original,'jbl_presentation':True};source=row.get('sources',{}).get('jbl',{});raw=source.get('raw_name') or (row.get('raw_names') or [row.get('normalized_name','')])[0];value=source.get('raw_value','')
  if re.search(r'\((?:in|lbs|lb|oz|ft)\)$',raw,re.I):continue # Equivalent metric measurements retain the original audit.
  row['display_name']=label(raw)
  resolved=dict(row.get('resolved') or {})
  if resolved.get('display_value') in {'Yes','Ja','yes','ja','Ya','ya'}:resolved['display_value']='Да'
  if resolved.get('display_value') in {'No','Nein','no','nein'}:resolved['display_value']='Нет'
  if resolved:row['resolved']=resolved
  # Only whole-product dimensions with explicit W x H x D cm axes; never case/earpiece.
  if raw in {'Dimensions (Width x Height x Depth) (cm)','Abmessungen (Breite x Höhe x Tiefe) (cm)','Dimensi (Lebar x Tinggi x Kedalaman) (cm)'} and re.fullmatch(r'\s*\d+(?:[.,]\d+)?\s*[x×]\s*\d+(?:[.,]\d+)?\s*[x×]\s*\d+(?:[.,]\d+)?\s*',value):
   numbers=re.findall(r'\d+(?:[.,]\d+)?',value)
   for dimension,number in zip(('Ширина','Высота','Глубина'),numbers):
    shown=str(Decimal(number.replace(',','.'))*10).rstrip('0').rstrip('.') if '.' in str(Decimal(number.replace(',','.'))*10) else str(Decimal(number.replace(',','.'))*10)
    key=dimension.lower()+'_товара_мм';result.append({**row,'display_name':dimension+' товара, мм','normalized_name':key,'derived_from':row['normalized_name'],'resolved':{**resolved,'display_value':shown,'selected_value':shown,'selected_unit':'mm'}})
   continue
  if raw=='Weight (g)' and re.fullmatch(r'\d+(?:[.,]\d+)?',value):
   number=str(Decimal(value.replace(',','.'))/1000);row['display_name']='Вес товара, кг';row['resolved']={**resolved,'display_value':number,'selected_value':number,'selected_unit':'kg'}
  result.append(row)
 return result
